const fmtD=s=>{try{return new Intl.DateTimeFormat('ar-SA-u-ca-gregory-nu-arab',{day:'numeric',month:'long'}).format(pd(s))}catch(x){return s}};
const fmtH=d=>{try{return new Intl.DateTimeFormat('ar-SA-u-ca-islamic-umalqura-nu-arab',{day:'numeric',month:'long',year:'numeric'}).format(d)}catch(x){return''}};
const num=v=>{const n=parseFloat(String(v).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace('٫','.').replace(/,/g,''));return isFinite(n)?n:0};
const money=n=>ar((Math.round(n*100)/100).toLocaleString('en-US'));
const hubBack=r=>{const s=ZS.hubOf(r);return s?`<button class="back" onclick="location.hash='sec/${s.id}'">${zi('chev')} ${s.n}</button>`:''};
const head=(r,sub)=>`${hubBack(r)}<h1 class="page">${F[r][0]}</h1>${sub?`<p class="znote">${sub}</p>`:''}`;
const CHN=n=>{try{if(typeof CH==='function'){const c=CH(n);const s=Array.isArray(c)?c[1]:typeof c==='string'?c:c&&(c.ar||c.name);if(typeof s==='string')return s}}catch(x){}return''};
const vref=k=>{const v=D.ay[k];return`${(CHN(v.sn)||v.s).replace(/^سورة\s*/,'')}: ${ar(v.a)}`};
const verse=(k,sm)=>{const v=D.ay[k];if(!v)return'';return`<div class="zb-v${sm?' sm':''}">﴿${v.t}﴾</div><div class="zref">[${vref(k)}]</div>`};
const verses=ks=>`<div class="zb-v${ks.length>1?' sm':''}">﴿${ks.map(k=>D.ay[k].t+' ('+ar(D.ay[k].a)+')').join(' ')}﴾</div><div class="zref">[${vref(ks[0]).split(':')[0]}: ${ks.map(k=>ar(D.ay[k].a)).join('–')}]</div>`;
const had=k=>{const h=D.h[k];if(!h)return'';return`<div class="zb-h"><div class="k">${h.w}:</div><div class="zhad">«${h.t}»</div><div class="zref"><a href="${h.u}" target="_blank" rel="noopener">${h.ref}</a> · ${h.g}</div></div>`};
const fq=k=>{const f=D.fq[k];return`<blockquote class="zb-q">${e(f.t).replace(/\n/g,'<br>')}<a href="${f.u}" target="_blank" rel="noopener">${f.n}</a></blockquote>`};
const srcNote='<p class="zb-src">الآيات من api.alquran.cloud بالرسم العثماني، والأحاديث بنصها من sunnah.com مع درجتها ورابطها.</p>';
const sec=(t,ic,body,extra)=>`<section class="zcard${extra?' '+extra:''}">${t?`<h3>${zi(ic||'dot')}${t}</h3>`:''}${body}</section>`;
const sw=(id,on,t,s)=>`<label class="zset"><span class="grow"><b>${t}</b>${s?`<small>${s}</small>`:''}</span><span class="zsw"><input type="checkbox" id="${id}" ${on?'checked':''}><i></i></span></label>`;
const perm=()=>window.Notification?Notification.permission:'unsupported';
const permNote=()=>perm()==='granted'?'<p class="zb-src">التذكير يصلك تنبيهًا على الجهاز، ويظهر أيضًا في جرس التنبيهات.</p>':`<p class="zb-src">التذكير يظهر داخل التطبيق وفي جرس التنبيهات. لتنبيه على الجهاز فعّل <a href="#push">التنبيهات</a>.</p>`;
